package com.tanluzhe.controlterminal.vr.v2;

import android.content.Context;
import com.tanluzhe.controlterminal.vr.AppLog;
import com.tanluzhe.controlterminal.vr.ConnectionSettings;
import java.nio.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import okhttp3.*;
import org.json.*;
import org.webrtc.*;

/** VR-side TLZ2 client. No robot commands are generated by demo mode. */
public final class BaseLink implements AutoCloseable {
  private final Dashboard ui;
  public final SceneStore scene;
  public final RobotScene robotScene;
  public final ControlGate gate = new ControlGate();
  public final ClockSync clocks = new ClockSync();
  private final ScheduledExecutorService timer = Executors.newSingleThreadScheduledExecutor();
  private final ExecutorService httpWorker = Executors.newFixedThreadPool(2);
  private final ThreadPoolExecutor sceneWorker =
      new ThreadPoolExecutor(1, 1, 0, TimeUnit.MILLISECONDS, new ArrayBlockingQueue<>(64), r -> {
        Thread t = new Thread(() -> {
          android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_BACKGROUND);
          r.run();
        }, "tlz-scene");
        return t;
      }, new ThreadPoolExecutor.DiscardOldestPolicy());
  private final Map<String, PeerConnection> peers = new ConcurrentHashMap<>();
  private final Map<String, DataChannel> channels = new ConcurrentHashMap<>();
  private final Map<String, List<IceCandidate>> waitingIce = new ConcurrentHashMap<>();
  private final Set<String> remoteReady = ConcurrentHashMap.newKeySet();
  private final AtomicLong sequence = new AtomicLong(), probeSequence = new AtomicLong();
  private final ConcurrentHashMap<Integer, AtomicLong> streamSequences = new ConcurrentHashMap<>();
  private final LossWindow loss = new LossWindow();
  private long lossAt, statsAt, rejectLogAt;
  private final RttHistory rttHistory = new RttHistory();
  private final ConcurrentHashMap<Long, Long> probes = new ConcurrentHashMap<>();
  private final AtomicReference<Input> latest = new AtomicReference<>();
  private final Map<String, Long> lastSeq = new ConcurrentHashMap<>();
  private final Set<Integer> streamIds = ConcurrentHashMap.newKeySet();
  private final Set<String> repairing = ConcurrentHashMap.newKeySet();
  private final Context context;
  public final VideoTiming videoTiming;
  private final String host, token;
  private final int port;
  private volatile boolean closed;
  private final AtomicBoolean failed = new AtomicBoolean();
  public Runnable disconnected = () -> {};
  public String bootId = UUID.randomUUID().toString();
  private volatile WebSocket events;
  private volatile OkHttpClient http;
  private volatile PeerConnectionFactory factory;
  private volatile long session;
  private volatile int node, baseNode = 1, carNode, epoch = 1, controlStream, operatorStream,
                             probeStream;
  private volatile long leaseLastRenew, started = System.nanoTime();
  private JSONObject config;
  private long manifestAt;
  private final AtomicBoolean manifestPending = new AtomicBoolean();
  private final ObservationRate observationRate;
  private String operatorEncoding = OperatorCompact.CBOR;
  private long observationStatsAt, observationPreviousCount, observationPreviousBytes;
  public static final class Input extends OperatorState.Sample {}
  public BaseLink(Context c, String h, int p, String bearer, EglBase e, VideoSink sink,
      Dashboard status, SceneStore store) {
    context = c;
    observationRate = new ObservationRate(new ConnectionSettings(c).observationHz);
    host = h;
    port = p;
    token = bearer;
    ui = status;
    scene = store;
    robotScene = new RobotScene(scene);
    videoTiming = new VideoTiming(clocks, ui);
    gate.foreground = true;
    scene.repair = this::repair;
  }
  public void input(Input in) {
    if (closed || failed.get())
      return;
    latest.set(in);
    gate.tracking = (in.flags & 7) == 7;
  }
  public void connect() {
    executeNetwork(() -> {
      try {
        if (token.isEmpty())
          throw new IllegalArgumentException("请先填写设备访问令牌");
        http = directClient();
        ui.connection = "正在注册AIPC…";
        AppLog.info("NET", "SESSION_BEGIN", root() + "/v2/sessions");
        JSONObject caps =
            new JSONObject()
                .put("max_message_bytes", 1100)
                .put("point_formats", new JSONArray(new int[] {1, 2, 3, 4}))
                .put("point_attribute_policy", "base_filtered")
                .put("compression", new JSONArray().put("none"))
                .put("video_codec", "HEVC")
                .put("video_transport", "hevc-fmp4")
                .put("face_buttons_revision", 1)
                .put("stick_buttons_revision", 1)
                .put("controller_geometry_revision", 1)
                .put("max_tile_bytes", 262144)
                .put("max_scene_points", 60000)
                .put("input_controls_revision", 1)
                .put("operator_encoding_profiles", new JSONArray().put("cbor").put("opbin1"))
                .put("operator_hz", observationRate.hz)
                .put("setpoint_owner", "aipc");
        if(context.getPackageName().endsWith(".mobile"))caps.put("input_device","phone_chassis").put("pose_tracking",false).put("control_scope","chassis_only");
        JSONObject request = new JSONObject()
                                 .put("protocol", "TLZ/2.0")
                                 .put("role", "vr")
                                 .put("device_uuid", deviceId())
                                 .put("boot_uuid", bootId)
                                 .put("capabilities", caps);
        JSONObject response = json("POST", "/v2/sessions", request);
        operatorEncoding = response.optString("operator_encoding", "cbor");
        if (!operatorEncoding.equals("cbor") && !operatorEncoding.equals("opbin1"))
          throw new IllegalArgumentException("AIPC选择了未支持的输入编码");
        AppLog.info("INPUT", "ENCODING_SELECTED", operatorEncoding);
        session = u64(response.getString("session_id"));
        node = response.getInt("node_id");
        baseNode = response.optInt("base_node_id", 1);
        epoch = response.optInt("clock_epoch", 1);
        config = json("GET", "/v2/config", null);
        configure(config);
        AppLog.info("NET", "SESSION_READY",
            "注册与配置成功 node=" + node + " operator_stream=" + operatorStream);
        videoTiming.localNode(node);
        synchronized (this) {
          if (closed)
            return;
          factory = PeerConnectionFactory.builder().createPeerConnectionFactory();
        }
        Request ws = new Request.Builder()
                         .url(endpoint("ws", host, port)
                             + "/v2/events?session_id=" + Long.toUnsignedString(session))
                         .header("Authorization", "Bearer " + token)
                         .build();
        events = http.newWebSocket(ws, new WebSocketListener() {
          @Override
          public void onOpen(WebSocket socket, Response r) {
            if (closed) {
              socket.close(1000, "closed");
              return;
            }
            events = socket;
            AppLog.info("NET", "WS_OPEN", "AIPC信令已连接");
            try {
              createPeer("control");
              // Point cloud is owned by SceneModeController; no legacy scene peer.
            } catch (Exception e) {
              fail("WebRTC启动失败：" + e.getMessage());
            }
          }
          @Override
          public void onMessage(WebSocket s, String text) {
            if (closed || failed.get())
              return;
            try {
              if (text.length() > 1024 * 1024)
                throw new IllegalArgumentException("WS message limit");
              event(new JSONObject(text));
            } catch (Exception e) {
              ui.rejected++;
              ui.warning = "AIPC事件无效：" + e.getMessage();
            }
          }
          @Override
          public void onFailure(WebSocket s, Throwable t, Response r) {
            if (!closed)
              fail("AIPC信令断开：" + t.getClass().getSimpleName());
          }
          @Override
          public void onClosed(WebSocket s, int code, String reason) {
            if (!closed)
              fail("AIPC信令已关闭");
          }
        });

        timer.scheduleAtFixedRate(this::observe, 0, observationRate.periodNs, TimeUnit.NANOSECONDS);
        timer.scheduleAtFixedRate(this::probe, 100, 100, TimeUnit.MILLISECONDS);
        timer.scheduleAtFixedRate(this::maintenance, 100, 100, TimeUnit.MILLISECONDS);
      } catch (Exception e) {
        fail("连接失败：" + e.getMessage());
      }
    });
  }
  private void executeNetwork(Runnable task) {
    if (closed)
      return;
    try {
      httpWorker.execute(task);
    } catch (RejectedExecutionException ignored) {
    }
  }
  private String deviceId() {
    android.content.SharedPreferences p = context.getSharedPreferences("v2", 0);
    String id = p.getString("device_uuid", "");
    if (id.isEmpty()) {
      id = UUID.randomUUID().toString();
      p.edit().putString("device_uuid", id).apply();
    }
    return id;
  }
  private static long u64(String v) {
    return Long.parseUnsignedLong(v);
  }
  private String root() {
    return endpoint("http", host, port);
  }
  private JSONObject json(String method, String path, JSONObject body) throws Exception {
    if (closed || failed.get())
      throw new java.io.InterruptedIOException("obsolete session");
    Request.Builder b =
        new Request.Builder().url(root() + path).header("Authorization", "Bearer " + token);
    if (!method.equals("GET"))
      b.method(method, RequestBody.create(body.toString(), MediaType.get("application/json")));
    try (Response r = http.newCall(b.build()).execute()) {
      AppLog.info("NET", "HTTP_RESULT", method + " " + path + " status=" + r.code());
      if (!r.isSuccessful())
        throw new IllegalStateException("HTTP " + r.code() + " " + path
            + (r.code() == 401 || r.code() == 403 ? " AIPC拒绝连接密钥" : ""));
      if (r.body() == null || r.body().contentLength() > 1024 * 1024)
        throw new IllegalStateException("JSON大小");
      byte[] data = bounded(r.body(), 1024 * 1024);
      if (closed || failed.get())
        throw new java.io.InterruptedIOException("obsolete session");
      return new JSONObject(new String(data, java.nio.charset.StandardCharsets.UTF_8));
    }
  }
  private static byte[] bounded(ResponseBody body, int max) throws java.io.IOException {
    java.io.ByteArrayOutputStream out = new java.io.ByteArrayOutputStream();
    java.io.InputStream in = body.byteStream();
    byte[] buffer = new byte[8192];
    int n;
    while ((n = in.read(buffer)) != -1) {
      if (out.size() + n > max)
        throw new java.io.IOException("Response exceeds limit");
      out.write(buffer, 0, n);
    }
    return out.toByteArray();
  }
  static String endpoint(String scheme, String host, int port) {
    if (!scheme.equals("http") && !scheme.equals("ws"))
      throw new IllegalArgumentException("Unsupported base transport");
    return scheme + "://" + host + ":" + port;
  }
  /** Direct private-network HTTP/WS; no certificate provisioning or TLS override. */
  static OkHttpClient directClient() {
    return new OkHttpClient.Builder()
        .followRedirects(false)
        .followSslRedirects(false)
        .connectTimeout(5, TimeUnit.SECONDS)
        .readTimeout(8, TimeUnit.SECONDS)
        .writeTimeout(5, TimeUnit.SECONDS)
        .pingInterval(10, TimeUnit.SECONDS)
        .build();
  }
  private synchronized void configure(JSONObject c) throws Exception {
    if (closed || failed.get())
      throw new IllegalStateException("obsolete config");
    if (!"base_filtered".equals(c.optString("point_attribute_policy")))
      throw new IllegalArgumentException("AIPC需要确认点属性处理策略 base_filtered");
    carNode = c.getInt("robot_node_id");
    JSONArray streams = c.getJSONArray("streams");
    if (streams.length() > 64)
      throw new IllegalArgumentException("Too many streams");
    for (int i = 0; i < streams.length(); i++) {
      JSONObject s = streams.getJSONObject(i);
      streamIds.add(s.getInt("id"));
      switch (s.getString("name")) {
        case "control.setpoint":
          controlStream = s.getInt("id");
          break;
        case "operator.state":
          operatorStream = s.getInt("id");
          break;
        case "probe":
          probeStream = s.getInt("id");
          break;
      }
    }
    if (controlStream == 0 || operatorStream == 0 || probeStream == 0)
      throw new IllegalArgumentException("缺少会话stream分配");
    JSONArray frames = c.getJSONArray("frames");
    for (int i = 0; i < frames.length(); i++) {
      JSONObject f = frames.getJSONObject(i);
      JSONArray a = f.getJSONArray("T_map_frame");
      float[] m = new float[16];
      for (int j = 0; j < 16; j++) m[j] = (float) a.getDouble(j);
      scene.transform(f.getInt("id"), m);
    }
    gate.referenceRevision = c.getInt("reference_revision");
    scene.matrix(c.getInt("target_base_frame_id"));
    scene.matrix(c.getInt("target_hand_frame_id"));
    scene.matrix(c.getInt("operator_frame_id"));
    scene.matrix(c.getInt("base_frame_id"));
    scene.selectEpoch(u64(c.getString("map_epoch")));
    robotScene.baseFrameId = c.getInt("base_frame_id");
    robotScene.sampleUsable = s -> {
      int source = (int) Cbor.number(s, 4, carNode);
      double age = clocks.ageMs(
          source, (int) Cbor.number(s, 1, 0), Cbor.number(s, 0, 0), node, System.nanoTime());
      return Double.isFinite(age) && age >= -clocks.uncertaintyMs(source, node) && age <= 100
          && (Cbor.number(s, 5, 0) & 4) == 0;
    };
  }
  private synchronized void createPeer(String kind) {
    if (closed || failed.get() || factory == null)
      return;
    PeerConnection.RTCConfiguration cfg =
        new PeerConnection.RTCConfiguration(Collections.emptyList());
    cfg.sdpSemantics = PeerConnection.SdpSemantics.UNIFIED_PLAN;
    cfg.tcpCandidatePolicy = PeerConnection.TcpCandidatePolicy.DISABLED;
    cfg.enableDscp = true;
    PeerConnection pc = factory.createPeerConnection(cfg, new PeerConnection.Observer() {
      public void onSignalingChange(PeerConnection.SignalingState s) {}
      public void onIceConnectionChange(PeerConnection.IceConnectionState s) {
        if (closed || failed.get())
          return;
        AppLog.info("RTC", "ICE_STATE", kind + " " + s);
        if (kind.equals("control")
            && (s == PeerConnection.IceConnectionState.FAILED
                || s == PeerConnection.IceConnectionState.DISCONNECTED
                || s == PeerConnection.IceConnectionState.CLOSED)) {
          gate.disarm();
          gate.connected = false;
          ui.connection = "输入链路断开";
          fail("AIPC输入链路断开，将重新注册");
        }
      }
      public void onIceConnectionReceivingChange(boolean b) {}
      public void onIceGatheringChange(PeerConnection.IceGatheringState s) {}
      public void onIceCandidate(IceCandidate c) {
        try {
          emit("ice.candidate",
              new JSONObject()
                  .put("pc", kind)
                  .put("sdpMid", c.sdpMid)
                  .put("sdpMLineIndex", c.sdpMLineIndex)
                  .put("candidate", c.sdp));
        } catch (JSONException e) {
          fail("ICE格式错误");
        }
      }
      public void onIceCandidatesRemoved(IceCandidate[] a) {}
      public void onAddStream(MediaStream s) {}
      public void onRemoveStream(MediaStream s) {}
      public void onDataChannel(DataChannel dc) {
        bind(dc);
      }
      public void onRenegotiationNeeded() {}
      public void onTrack(RtpTransceiver t) {}
    });
    if (pc == null)
      throw new IllegalStateException("Cannot create PeerConnection");
    peers.put(kind, pc);
    if (kind.equals("control")) {
      channel(pc, "tlz.ctrl.v2");
      channel(pc, "tlz.probe.v2");
    } else {
      channel(pc, "tlz.scene.v2");
    }
    pc.createOffer(new SdpObserver() {
      public void onCreateSuccess(SessionDescription offer) {
        pc.setLocalDescription(new SimpleSdp() {
          @Override
          public void onSetSuccess() {
            executeNetwork(() -> {
              try {
                JSONObject answer = json("POST",
                    "/v2/sessions/" + Long.toUnsignedString(session) + "/webrtc/" + kind,
                    new JSONObject().put("type", "offer").put("sdp", offer.description));
                pc.setRemoteDescription(new SimpleSdp() {
                  @Override
                  public void onSetSuccess() {
                    remoteReady.add(kind);
                    List<IceCandidate> q = waitingIce.remove(kind);
                    if (q != null)
                      for (IceCandidate ice : q) pc.addIceCandidate(ice);
                  }
                }, new SessionDescription(SessionDescription.Type.ANSWER, answer.getString("sdp")));
              } catch (Exception e) {
                fail("SDP协商失败：" + e.getMessage());
              }
            });
          }
        }, offer);
      }
      public void onSetSuccess() {}
      public void onCreateFailure(String e) {
        fail(e);
      }
      public void onSetFailure(String e) {
        fail(e);
      }
    }, new MediaConstraints());
  }
  private class SimpleSdp implements SdpObserver {
    public void onCreateSuccess(SessionDescription s) {}
    public void onSetSuccess() {}
    public void onCreateFailure(String s) {
      fail(s);
    }
    public void onSetFailure(String s) {
      fail(s);
    }
  }
  private void channel(PeerConnection p, String name) {
    DataChannel.Init init = new DataChannel.Init();
    init.ordered = false;
    init.maxRetransmits = 0;
    init.protocol = "tlz/2.0";
    bind(p.createDataChannel(name, init));
  }
  private void bind(DataChannel dc) {
    if (dc.label().equals("tlz.scene.v2") || closed || failed.get()) {
      dc.close();
      return;
    }
    if (!Arrays.asList("tlz.ctrl.v2", "tlz.probe.v2", "tlz.scene.v2").contains(dc.label())) {
      dc.close();
      return;
    }
    DataChannel previous = channels.putIfAbsent(dc.label(), dc);
    if (previous != null && previous != dc) {
      dc.close();
      return;
    }
    dc.registerObserver(new DataChannel.Observer() {
      public void onBufferedAmountChange(long n) {}
      public void onStateChange() {
        if (closed || failed.get())
          return;
        AppLog.info("RTC", "CHANNEL_STATE", dc.label() + " " + dc.state());
        if (dc.label().equals("tlz.ctrl.v2")) {
          gate.connected = dc.state() == DataChannel.State.OPEN;
          ui.connection = gate.connected ? "AIPC已连接 · 等待车端/对时" : "控制通道未就绪";
          if (!gate.connected)
            gate.disarm();
        }
        DataChannel ctrl=channels.get("tlz.ctrl.v2"),probe=channels.get("tlz.probe.v2");
        boolean ready=(ctrl!=null&&ctrl.state()==DataChannel.State.OPEN)||(probe!=null&&probe.state()==DataChannel.State.OPEN);
        if(ready&&!ui.inputConnected)ui.warning="";
        ui.inputConnected=ready;
      }
      public void onMessage(DataChannel.Buffer b) {
        if (!b.binary || b.data.remaining() > 1100)
          return;
        byte[] a = new byte[b.data.remaining()];
        b.data.get(a);
        if (dc.label().equals("tlz.scene.v2")) {
          if (!closed)
            sceneWorker.execute(() -> receive(a));
        } else
          receive(a);
      }
    });
  }
  private void emit(String type, JSONObject payload) {
    WebSocket ws = events;
    if (ws == null || closed)
      return;
    try {
      if (ws.queueSize() > 32768) {
        fail("信令背压，控制已撤销");
        return;
      }
      ws.send(new JSONObject()
                  .put("event_id", UUID.randomUUID().toString())
                  .put("type", type)
                  .put("session_id", Long.toUnsignedString(session))
                  .put("payload", payload)
                  .toString());
    } catch (JSONException e) {
      fail("事件编码失败");
    }
  }
  private void event(JSONObject envelope) throws Exception {
    if (!envelope.has("session_id") || u64(envelope.getString("session_id")) != session)
      return;
    String type = envelope.getString("type");
    JSONObject p = envelope.getJSONObject("payload");
    if (type.equals("ice.candidate")) {
      String kind = p.getString("pc");
      if (!kind.equals("control") && !kind.equals("media"))
        return;
      IceCandidate ice = new IceCandidate(
          p.optString("sdpMid", null), p.getInt("sdpMLineIndex"), p.getString("candidate"));
      PeerConnection pc = peers.get(kind);
      if (pc != null && remoteReady.contains(kind))
        pc.addIceCandidate(ice);
      else
        waitingIce.computeIfAbsent(kind, k -> Collections.synchronizedList(new ArrayList<>()))
            .add(ice);
    } else if (type.equals("clock.mapping")) {
      ClockSync.Mapping m = new ClockSync.Mapping();
      m.node = p.getInt("node_id");
      m.epoch = p.getInt("epoch");
      m.refLocal = u64(p.getString("ref_X"));
      m.refBase = u64(p.getString("ref_B"));
      m.updatedBase = u64(p.getString("updated_B_ns"));
      m.uncertainty = u64(p.getString("uncertainty_ns"));
      m.drift = p.optDouble("drift_ppb", 0) * 1e-9;
      clocks.install(m);
      gate.clockConfirmed = true;
    } else if (type.equals("config.changed")) {
      fail("AIPC配置改变，重新注册");
    } else if (type.equals("map.manifest.changed")) {
      requestManifest();
    } else if (type.equals("event.result") && p.optString("status").equals("rejected")) {
      ui.warning = "请求被拒绝：" + p.optString("reason");
    }
  }
  private synchronized void receive(byte[] bytes) {
    if (closed || failed.get())
      return;
    try {
      Packet p = Packet.decode(bytes);
      if (p.session != session || !streamIds.contains(p.stream)
          || p.node != baseNode && p.node != carNode && p.node != node)
        throw new IllegalArgumentException("来源/会话");
      long now = System.nanoTime();
      ui.packets++;
      if (p.type == Packet.TIME_RESP) {
        long id = Cbor.number(p.body, 0, 0);
        Long t1 = probes.remove(id);
        if (t1 != null && Cbor.number(p.body, 1, -1) == t1 && p.node == baseNode) {
          ClockSync.Mapping m = clocks.sample(
              node, epoch, t1, Cbor.number(p.body, 2, 0), Cbor.number(p.body, 3, 0), now);
          if (m != null) {
            ui.baseRtt =
                ((now - t1) - (Cbor.number(p.body, 3, 0) - Cbor.number(p.body, 2, 0))) / 1e6;
            rttHistory.add(ui.baseRtt, now);
            JSONObject mapping = new JSONObject()
                                     .put("node_id", node)
                                     .put("epoch", epoch)
                                     .put("ref_X", Long.toString(m.refLocal))
                                     .put("ref_B", Long.toString(m.refBase))
                                     .put("updated_B_ns", Long.toString(m.updatedBase))
                                     .put("uncertainty_ns", Long.toString(m.uncertainty))
                                     .put("drift_ppb", 0);
            emit("clock.mapping.propose", mapping);
          }
        }
        return;
      }
      if (p.type == Packet.PONG) {
        long id = Cbor.number(p.body, 0, 0);
        Long t = probes.remove(id);
        if (t != null && Cbor.number(p.body, 1, -1) == t) {
          double rtt = (now - t) / 1e6;
          if (Cbor.number(p.body, 2, baseNode) == carNode)
            ui.endRtt = rtt;
          else {
            ui.baseRtt = rtt;
            rttHistory.add(rtt, now);
          }
        }
        return;
      }
      if (p.type == Packet.PING) {
        send(Packet.PONG, probeStream, 0,
            Cbor.map(0, Cbor.number(p.body, 0, 0), 1, Cbor.number(p.body, 1, 0), 2, node, 3, 0),
            "tlz.probe.v2", now);
        return;
      }
      double age = clocks.ageMs(p.node, p.epoch, p.time, node, now);
      if (p.type == Packet.VIDEO_META) {
        videoTiming.metadata(p);
        return;
      } // retain stale metadata to reject stale video output
      if (p.ttlMs > 0 && Double.isFinite(age) && age > p.ttlMs)
        return;
      if (p.type == Packet.STATE || p.type == Packet.RECEIPT)
        loss.receive(p, now);
      if (p.type == Packet.STATE || p.type == Packet.RECEIPT || p.type == Packet.STATS
          || p.type == Packet.SCENE) {
        String key = p.node + "/" + p.stream;
        long old = lastSeq.getOrDefault(key, 0L);
        if (Long.compareUnsigned(p.seq, old) <= 0)
          return;
        lastSeq.put(key, p.seq);
      }
      if (p.type == Packet.STATE) {
        ui.stateReceived = now;
        robotScene.state(p, now);
        if (p.body.get(15L) instanceof Map)
          receipt(Cbor.object(p.body.get(15L)), now);
        if (p.body.containsKey(2L)) {
          gate.robotReady = Cbor.number(p.body, 2, 0) == 1 || Cbor.number(p.body, 2, 0) == 2;
          ui.robot = "车端模式 " + Cbor.number(p.body, 2, 0);
          if (Cbor.number(p.body, 2, 0) >= 3)
            gate.disarm();
        }
      } else if (p.type == Packet.RECEIPT) {
        receipt(p.body, now);
      } else if (p.type == Packet.STATS) {
        Object r = p.body.get(10L);
        if (r instanceof Number)
          ui.carRtt = ((Number) r).doubleValue();
      } else if (p.type == Packet.CLOUD || p.type == Packet.TILE) {
        acceptScene(p, now);
        ui.cloudReceived = now;
      } else if (p.type == Packet.SCENE)
        robotScene.display(p, now);
      else if (p.type == Packet.VIDEO_META)
        videoTiming.metadata(p);
    } catch (Exception e) {
      ui.rejected++;
      if (System.nanoTime() - rejectLogAt > 1_000_000_000L) {
        rejectLogAt = System.nanoTime();
        AppLog.warn("PROTO", "PACKET_REJECT", AppLog.reason(e));
      }
    }
  }
  private Packet packet(int type, int stream, int ttl, Map<Long, Object> body, long time) {
    Packet p = new Packet();
    p.type = type;
    p.node = node;
    p.stream = stream;
    p.epoch = epoch;
    p.ttlMs = ttl;
    p.session = session;
    p.seq = streamSequences.computeIfAbsent(stream, k -> new AtomicLong()).incrementAndGet();
    p.time = time;
    p.trace = sequence.incrementAndGet();
    p.body = body;
    return p;
  }
  private void receipt(Map<Long, Object> body, long now) {
    if (Cbor.number(body, 0, -1) != node)
      return;
    Map<Long, Object> stamps =
        body.get(6L) instanceof Map ? Cbor.object(body.get(6L)) : Collections.emptyMap();
    if (Cbor.number(body, 4, 0) == 4) {
      gate.disarm();
      ui.warning = "车端拒绝控制，原因码 " + Cbor.number(body, 5, 0);
    }
    if (stamps.containsKey(0L) && stamps.containsKey(4L)) {
      ClockSync.Mapping a = clocks.get(carNode), v = clocks.get(node);
      double error = clocks.uncertaintyMs(carNode, node);
      if (a != null && v != null && clocks.fresh(carNode, node, now) && error <= 20
          && Cbor.number(body, 7, a.epoch) == a.epoch) {
        ui.controlAge =
            (a.base(Cbor.number(stamps, 4, 0)) - v.base(Cbor.number(stamps, 0, 0))) / 1e6;
        ui.controlError = error;
      } else {
        ui.controlAge = Double.NaN;
        ui.controlError = Double.NaN;
      }
    }
    if (stamps.containsKey(2L) && stamps.containsKey(3L))
      ui.baseResidence = (Cbor.number(stamps, 3, 0) - Cbor.number(stamps, 2, 0)) / 1e6;
  }
  private boolean send(
      int type, int stream, int ttl, Map<Long, Object> body, String label, long time) {
    DataChannel dc = channels.get(label);
    if (closed || failed.get() || dc == null || dc.state() != DataChannel.State.OPEN
        || dc.bufferedAmount() > 2200)
      return false;
    return dc.send(new DataChannel.Buffer(
        ByteBuffer.wrap(packet(type, stream, ttl, body, time).encode()), true));
  }
  private void observe() {
    if (closed || failed.get() || operatorStream == 0)
      return;
    long now = System.nanoTime();
    Input in = latest.get();
    if (in == null)
      return;
    try {
      Map<Long, Object> body = OperatorState.body(in, now, gate.foreground, 0,
          streamSequences.getOrDefault(controlStream, new AtomicLong()).get(),
          config.getInt("operator_frame_id"));
      body = OperatorCompact.choose(body, operatorEncoding);
      DataChannel control = channels.get("tlz.ctrl.v2");
      String label = control != null && control.state() == DataChannel.State.OPEN ? "tlz.ctrl.v2"
                                                                                  : "tlz.probe.v2";
      DataChannel channel = channels.get(label);
      if (channel == null || channel.state() != DataChannel.State.OPEN
          || channel.bufferedAmount() > 2200) {
        ui.observationDropped++;
        return;
      }
      Packet packet = packet(Packet.OPERATOR, operatorStream, 1000, body, in.time);
      byte[] bytes = packet.encode();
      if (bytes.length > 1100)
        throw new IllegalArgumentException("OPERATOR_STATE exceeds1100");
      if (channel.send(new DataChannel.Buffer(ByteBuffer.wrap(bytes), true))) {
        ui.observationSent++;
          ui.observationTotalBytes+=bytes.length;
        ui.observationBytes = bytes.length;
        ui.observationChannel = label;
        ui.observationEncoding = body.containsKey(12L) ? operatorEncoding : "cbor";
      } else
        ui.observationDropped++;
      if (now - observationStatsAt >= 1_000_000_000L) {
        ui.observationActualHz = observationStatsAt == 0
            ? Double.NaN
            : (ui.observationSent - observationPreviousCount) * 1e9 / (now - observationStatsAt);
        ui.observationBytesPerSecond=observationStatsAt==0?Double.NaN:(ui.observationTotalBytes-observationPreviousBytes)*1e9/(now-observationStatsAt);
        observationPreviousBytes=ui.observationTotalBytes;
        observationStatsAt = now;
        observationPreviousCount = ui.observationSent;
        AppLog.info("INPUT", "OBSERVATION",
            "key11 rev=1 valid=" + in.controls.valid + " sent=" + ui.observationSent
                + " drop=" + ui.observationDropped + " bytes=" + bytes.length
                + " encoding=" + ui.observationEncoding
                + " Hz=" + String.format(Locale.ROOT, "%.1f", ui.observationActualHz)
                + " channel=" + label + " direct input; no local enable or setpoints");
      }
    } catch (Exception e) {
      ui.observationDropped++;
      gate.disarm();
      AppLog.error("INPUT", "ENCODE_FAILED", AppLog.reason(e));
    }
  }
  private void probe() {
    try {
      if (closed || probeStream == 0)
        return;
      long now = System.nanoTime(), id = probeSequence.incrementAndGet();
      if (probes.size() > 100)
        probes.clear();
      probes.put(id, now);
      send(Packet.PING, probeStream, 1000,
          Cbor.map(0, id, 1, now, 2, id % 2 == 0 ? baseNode : carNode, 3, 0), "tlz.probe.v2", now);
      if (now - started < 2_000_000_000L || id % 5 == 0) {
        long sync = probeSequence.incrementAndGet();
        probes.put(sync, now);
        send(Packet.TIME_REQ, probeStream, 1000, Cbor.map(0, sync, 1, now, 2, epoch),
            "tlz.probe.v2", now);
      }
    } catch (Exception e) {
      ui.warning = "探测失败";
    }
  }
  private void maintenance() {
    try {
      if (closed)
        return;
      long now = System.nanoTime();
      scene.expire(now);
      if (ui.stateReceived > 0 && now - ui.stateReceived > 100_000_000L) {
        gate.robotReady = false;
        gate.disarm();
        ui.robot = "机器人状态已过期";
      }
      if (now - manifestAt > 2_000_000_000L) {
        manifestAt = now;
        requestManifest();
      }
      if (now - statsAt > 1_000_000_000L) {
        statsAt = now;
        long[] n = loss.peek();
        Map<Long, Object> stats =
            Cbor.map(0, 10000, 1, n[0] + n[1], 2, n[0], 3, n[1], 4, n[2], 5, n[3]);
        float[] rtt = rttHistory.summary(now);
        if (rtt != null)
          for (int i = 0; i < 4; i++) stats.put(6L + i, rtt[i]);
        if (Double.isFinite(ui.carRtt))
          stats.put(10L, (float) ui.carRtt);
        send(Packet.STATS, probeStream, 2000, stats, "tlz.probe.v2", now);
      }
      if (now - lossAt > 10_000_000_000L) {
        lossAt = now;
        loss.expire(now);
        long[] counts = loss.snapshot();
        ui.feedbackLoss =
            counts[0] + counts[1] == 0 ? Double.NaN : 100.0 * counts[1] / (counts[0] + counts[1]);
      }
    } catch (Exception e) {
      ui.warning = "状态维护失败：" + e.getMessage();
    }
  }
  public void stop(String reason) {
    AppLog.warn("CONTROL", "STOP", reason);
    gate.disarm();
    gate.stopLatched = true;
    ui.warning = reason;
    try {
      String event = UUID.randomUUID().toString();
      byte[] id = ByteBuffer.allocate(16)
                      .putLong(UUID.fromString(event).getMostSignificantBits())
                      .putLong(UUID.fromString(event).getLeastSignificantBits())
                      .array();
      send(Packet.STOP, controlStream, 0, Cbor.map(0, id, 1, Cbor.u(gate.lease), 2, 0, 3, true),
          "tlz.ctrl.v2", System.nanoTime());
      for (int delay : new int[] {10, 20, 40, 80})
        timer.schedule(()
                           -> send(Packet.STOP, controlStream, 0,
                               Cbor.map(0, id, 1, Cbor.u(gate.lease), 2, 0, 3, true), "tlz.ctrl.v2",
                               System.nanoTime()),
            delay, TimeUnit.MILLISECONDS);

    } catch (Exception ignored) {
    }
  }
  private synchronized void acceptScene(Packet packet, long now) {
    if (!closed && !failed.get())
      scene.accept(packet, now);
  }
  private synchronized void publishTile(Packet packet, byte[] bytes) {
    if (!closed && !failed.get())
      scene.publish(packet, bytes);
  }
  private synchronized void selectMapEpoch(long value) {
    if (!closed && !failed.get())
      scene.selectEpoch(value);
  }
  private void requestManifest() {
    if (!manifestPending.compareAndSet(false, true))
      return;
    executeNetwork(() -> {
      try {
        JSONObject manifest =
            json("GET", "/v2/maps/" + config.getString("map_epoch") + "/manifest", null);
        JSONArray tiles = manifest.getJSONArray("tiles");
        if (u64(manifest.getString("map_epoch")) != u64(config.getString("map_epoch")))
          throw new IllegalArgumentException("Map epoch changed; reconnect required");
        selectMapEpoch(u64(manifest.getString("map_epoch")));
        for (int i = 0; i < Math.min(tiles.length(), 64); i++) {
          JSONObject t = tiles.getJSONObject(i);
          Packet descriptor = descriptor(manifest, t);
          if (t.optBoolean("deleted", false)) {
            descriptor.body.put(26L, 1L);
            descriptor.body.put(6L, 0L);
            descriptor.body.put(11L, 0L);
            descriptor.body.put(12L, new byte[0]);
            acceptScene(descriptor, System.nanoTime());
          } else if (scene.needs(descriptor))
            repair(descriptor);
        }
      } catch (Exception e) {
        ui.warning = "地图清单暂不可用";
      } finally {
        manifestPending.set(false);
      }
    });
  }
  private Packet descriptor(JSONObject manifest, JSONObject t) throws Exception {
    JSONArray xyz = t.getJSONArray("tile"), o = t.getJSONArray("origin");
    Packet p = new Packet();
    p.type = Packet.TILE;
    p.body = Cbor.map(2, t.getInt("coordinate_frame_id"), 3, t.getInt("transform_revision"), 4, 0,
        5, 1, 6, t.optInt("point_count", 0), 7, t.getInt("format"), 8,
        new float[] {(float) o.getDouble(0), (float) o.getDouble(1), (float) o.getDouble(2)}, 9,
        (float) t.getDouble("scale_m"), 10, 0, 11, t.getInt("object_size_bytes"), 12, new byte[0],
        20, Cbor.u(u64(manifest.getString("map_epoch"))), 21,
        Arrays.asList(xyz.getLong(0), xyz.getLong(1), xyz.getLong(2)), 22,
        Cbor.u(u64(t.getString("version"))), 23, t.getInt("lod"), 24, t.getInt("object_size_bytes"),
        25, android.util.Base64.decode(t.getString("sha256"), android.util.Base64.DEFAULT), 26,
        t.optBoolean("deleted", false) ? 1 : 0);
    return p;
  }
  private void repair(Packet p) {
    if (closed || http == null)
      return;
    String path;
    try {
      List<?> tile = (List<?>) p.body.get(21L);
      path = "/v2/maps/" + Long.toUnsignedString(Cbor.number(p.body, 20, 0)) + "/tiles/"
          + tile.get(0) + "," + tile.get(1) + "," + tile.get(2) + "/"
          + Long.toUnsignedString(Cbor.number(p.body, 22, 0)) + "/" + Cbor.number(p.body, 23, 0);
    } catch (Exception e) {
      return;
    }
    if (repairing.size() >= 2 || !repairing.add(path))
      return;
    executeNetwork(() -> {
      try {
        Request r = new Request.Builder()
                        .url(root() + path)
                        .header("Authorization", "Bearer " + token)
                        .build();
        try (Response response = http.newCall(r).execute()) {
          if (response.isSuccessful() && response.body() != null
              && response.body().contentLength() <= 262144)
            publishTile(p, bounded(response.body(), 262144));
        }
      } catch (Exception e) {
        ui.warning = "地图补块等待重试";
      } finally {
        repairing.remove(path);
      }
    });
  }
  private void fail(String reason) {
    if (closed || !failed.compareAndSet(false, true))
      return;
    gate.reset();ui.inputConnected=false;
    latest.set(null);
    clocks.reset();
    probes.clear();
    lastSeq.clear();
    session = 0;
    ui.baseRtt = ui.endRtt = ui.carRtt = ui.controlAge = Double.NaN;
    ui.observationActualHz = Double.NaN;
    AppLog.error("NET", "LINK_FAILED", reason);
    ui.connection = reason;
    ui.warning = "输入连接中断，清理旧会话后自动重连";
    disconnected.run();
  }
  @Override
  public void close() {
    synchronized (this) {
      if (closed)
        return;
      closed = true;
    }
    latest.set(null);
    clocks.reset();
    probes.clear();
    session = 0;
    gate.reset();ui.inputConnected=false;
    timer.shutdownNow();
    if (events != null)
      events.close(1000, "VR closed");
    for (PeerConnection p : peers.values()) {
      p.close();
      p.dispose();
    }
    peers.clear();
    channels.clear();
    if (factory != null) {
      factory.dispose();
      factory = null;
    }
    httpWorker.shutdownNow();
    sceneWorker.shutdownNow();
    if (http != null) {
      http.dispatcher().cancelAll();
      http.connectionPool().evictAll();
    }
  }
}
